alter table public.profiles enable row level security; alter table public.prospects enable row level security; alter table public.prospect_notes enable row level security; alter table public.activities enable row level security; alter table public.follow_ups enable row level security; alter table public.tasks enable row level security; alter table public.communications enable row level security; alter table public.communication_drafts enable row level security; alter table public.automation_rules enable row level security; alter table public.automation_logs enable row level security; alter table public.message_templates enable row level security; alter table public.services enable row level security; alter table public.sales_goals enable row level security; alter table public.ai_results enable row level security;
create policy "profile owner" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create or replace function public.owner_row() returns trigger language plpgsql security definer set search_path=public as $$ begin new.user_id=auth.uid(); return new; end; $$;
create or replace function public.apply_owner_trigger() returns void language plpgsql as $$ declare t text; begin foreach t in array array['prospects','prospect_notes','activities','follow_ups','tasks','communications','communication_drafts','automation_rules','automation_logs','message_templates','services','sales_goals','ai_results'] loop execute format('create trigger set_owner before insert on public.%I for each row execute function public.owner_row()',t); execute format('create policy user_rows on public.%I for all using (user_id=auth.uid()) with check (user_id=auth.uid())',t); end loop; end $$; select public.apply_owner_trigger(); drop function public.apply_owner_trigger();
create index prospects_user_id_idx on public.prospects(user_id); create index prospects_stage_idx on public.prospects(stage); create index prospects_email_idx on public.prospects(email); create index prospects_phone_idx on public.prospects(phone); create index tasks_user_id_idx on public.tasks(user_id); create index follow_ups_user_id_idx on public.follow_ups(user_id); create index activities_prospect_id_idx on public.activities(prospect_id); create index communications_prospect_id_idx on public.communications(prospect_id);
